import {createInteriors} from './interiors.js';
import {STORY_TITLE,CAST,objective,storyDestination,storyItems,advanceStory,conversation,conversationBranch} from './story.js';
import {EXPEDITION_TITLE,expeditionObjective,advanceExpedition} from './expedition.js';
import {CITY_NAMES} from './places.js';
export function createQuestExperience(renderer,{getState,save,toast,keys,onExit,onCourse,onService}){
const $=id=>document.getElementById(id);document.body.insertAdjacentHTML('beforeend',`<section id="room-ui" hidden><div class="room-heading"><div><small id="room-city"></small><h1 id="room-title"></h1></div><button id="leave-room">Return <span>Esc</span></button></div><div class="room-story"><small>ON FOOT</small><span id="room-objective"></span></div><div id="town-labels"></div><div id="town-directory" hidden><div class="directory-heading"><h2>Places to visit</h2><button id="close-directory" aria-label="Close places">✕</button></div><p>Select a place to walk there.</p><div id="room-people"></div></div><div class="room-controls"><div><b>Explore on foot</b><span>WASD / arrows · Click to walk · E to interact</span></div><button id="room-talk">Explore the town <kbd>E</kbd></button><button id="open-directory">Places & people</button></div><div id="walk-pad" aria-label="Directional walking controls"><button data-walk="w" aria-label="Walk north">▲</button><button data-walk="a" aria-label="Walk west">◀</button><button data-walk="s" aria-label="Walk south">▼</button><button data-walk="d" aria-label="Walk east">▶</button></div></section><dialog id="story-dialogue" aria-labelledby="speaker-name" aria-describedby="speaker-text"><div class="portrait" id="speaker-portrait" role="img"></div><div class="dialogue-copy"><div class="dialogue-top"><div><small id="speaker-role"></small><h2 id="speaker-name"></h2></div><button id="dialogue-close" aria-label="Leave conversation">✕</button></div><p id="speaker-text"></p><div id="dialogue-choices"></div></div></dialog>`);
const dialog=$('story-dialogue'),positions=new Map();let lastSpeaker=null;const labels=new Map();const room=createInteriors(renderer,{talk:openConversation,onAction:placeAction,onNearby(point){$('room-talk').textContent=point?`${point.door?'':'Talk to '}${point.name} · E`:'Approach a doorway or character · E';}});
function closeDialogue(){dialog.close();keys.clear();$('room-talk').focus({preventScroll:true});}
function showNode(node){lastSpeaker=node.speaker;const c=CAST[node.speaker]||{name:node.title||'Captain’s journal',role:node.subtitle||EXPEDITION_TITLE,portrait:null};const illustrated=c.portrait!==null;dialog.classList.toggle('without-portrait',!illustrated);$('speaker-name').textContent=c.name;$('speaker-role').textContent=c.role;$('speaker-text').textContent=node.text;$('speaker-portrait').hidden=!illustrated;if(illustrated){$('speaker-portrait').style.backgroundPosition=`${c.portrait%2*100}% ${Math.floor(c.portrait/2)*100}%`;$('speaker-portrait').setAttribute('aria-label',`Portrait of ${c.name}`);}const choices=$('dialogue-choices');choices.replaceChildren();for(const option of node.choices){const b=document.createElement('button');b.textContent=option.label;b.onclick=()=>{if(option.close){closeDialogue();return;}if(option.perform){option.perform();return;}if(option.next){showNode(option.next==='start'?conversation(getState(),lastSpeaker):conversationBranch(getState(),lastSpeaker,option.next));return;}if(option.action){const result=advanceStory(getState(),option.action,room.place);if(!result.ok){toast(result.message);closeDialogue();return;}save();toast(result.message);showNode({speaker:lastSpeaker,text:option.after,choices:[{label:'Continue',close:true}]});}};choices.append(b);}if(dialog.open)choices.firstElementChild?.focus({preventScroll:true});}
function speak(node){keys.clear();$('town-directory').hidden=true;showNode(node);if(!dialog.open)dialog.showModal();}
function openConversation(id){if(dialog.open)return;speak(conversation(getState(),id));}
function note(text,choices=[{label:'Close journal',close:true}],title){speak({speaker:'journal',title,text,choices});}
function expeditionAction(action){const r=advanceExpedition(getState(),action,room.place);if(r.ok){save();toast(r.message);note(r.message);}else toast(r.message);}
function archive(){const s=getState(),phase=s.expedition.phase;if(room.place==='lisbon-archive'&&phase==='locked'&&s.story.phase==='complete'){note('Tucked inside the Morning Star’s ledger is a letter: “Follow the eastern star. The archive in Alexandria holds the first half of the chart; a courtyard in the hills beyond holds the rest.” A new voyage begins on these old pages.',[{label:'Begin The Eastern Star',perform:()=>expeditionAction('accept')},{label:'Leave the letter for now',close:true}]);return;}if(room.place==='alexandria-archive'&&phase==='alexandria'){note('The archivist unfolds a weather-stained itinerary. It leads east with a caravan, toward a pilgrim’s courtyard near Jerusalem. There, travelers once carved the positions of the stars into a stone table. Copy the chart and leave the original for those who follow.',[{label:'Copy the caravan itinerary',perform:()=>expeditionAction('read')},{label:'I’ll return later',close:true}]);return;}if(room.place==='alexandria-archive'&&phase==='recorded'){note('Your sketch fits the missing half of the archive’s chart. The keeper prepares a clean copy for future travelers and offers a patron’s purse for your work.',[{label:'Preserve the chart · receive 450 gold',perform:()=>expeditionAction('finish')},{label:'Keep studying it for now',close:true}]);return;}note(expeditionObjective(s));}
function placeAction(action){if(action.type==='door'){enter(action.target);return;}if(action.type==='ship'){exit();return;}if(['market','shipyard','guild'].includes(action.type)){keys.clear();onService(action.city,action.type==='shipyard'?'shipyard':'market');return;}if(action.type==='archive'){archive();return;}if(action.type==='chapel'){note('The noise of the harbor fades behind the thick stone walls. A sailor has left a small lantern for someone still at sea. You rest a moment, then return to the road.',[{label:'Return to exploring',close:true}],'A moment of quiet');return;}if(action.type==='tavern'){note('A table of sailors trade stories of Lisbon, London, and the long crossing east. “If you seek old maps,” one says, “try the cartographer’s archive.”',[{label:'Thank them for the rumor',close:true}],'Harbor rumors');return;}if(action.type==='caravan'){const s=getState();if(!['courtyard','recorded','complete'].includes(s.expedition.phase)){note('The caravan master needs a destination before you can join the eastern route. Visit Alexandria’s cartographer’s archive with the letter from Lisbon.');return;}note('The caravan follows the coast, then turns inland through olive groves and pale hills. Travel to the Pilgrim’s Courtyard near Jerusalem. The passage takes one day and one provision.',[{label:'Travel to the Holy Land · 1 provision',perform:()=>{if(s.supplies<1){toast('Restock provisions before taking the caravan.');return;}s.supplies-=1;s.time+=1440;closeDialogue();enter('holyland');save();}},{label:'Stay in Alexandria',close:true}]);return;}if(action.type==='star-chart'){if(getState().expedition.phase==='courtyard')note('Time has softened the lines, but the stars remain. Kneeling beside the stone table, you trace the chart into your journal. The original belongs here, beneath the same sky that inspired it.',[{label:'Copy the chart into your journal',perform:()=>expeditionAction('record')},{label:'Look around first',close:true}]);else note('The old chart rests beneath the open sky. '+expeditionObjective(getState()));}}
$('dialogue-close').onclick=closeDialogue;dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialogue();});dialog.addEventListener('close',()=>keys.clear());$('room-talk').onclick=()=>room.interact();$('open-directory').onclick=()=>{$('town-directory').hidden=!$('town-directory').hidden;keys.clear();};$('close-directory').onclick=()=>{$('town-directory').hidden=true;};
for(const b of document.querySelectorAll('[data-walk]')){b.onpointerdown=e=>{if(dialog.open)return;e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.walk);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.walk);}
function enter(place){if(dialog.open)closeDialogue();if(room.active)positions.set(room.place,room.position);keys.clear();room.enter(place,positions.get(place));document.body.classList.add('in-room');document.body.classList.toggle('in-town',['town','special'].includes(room.spec.kind));$('room-ui').hidden=false;$('town-directory').hidden=true;$('room-city').textContent=room.spec.city==='jerusalem'?'THE HOLY LAND · HILLS NEAR JERUSALEM':room.spec.city==='azores'?'AZORES · ATLANTIC OCEAN':`${CITY_NAMES[room.spec.city].toUpperCase()} · ${room.spec.kind==='town'?'HARBOR QUARTER':'ASHORE'}`;$('room-title').textContent=room.spec.title;$('room-objective').textContent=place==='holyland'?'Explore the courtyard and its weathered star chart':room.spec.kind==='town'?'Streets, stories, and places to discover':STORY_TITLE;$('leave-room').textContent=room.spec.parent?'Return to town · Esc':'Return to ship · Esc';$('room-people').replaceChildren();$('town-labels').replaceChildren();labels.clear();for(const point of room.points){const b=document.createElement('button');b.textContent=point.name;b.onclick=()=>{$('town-directory').hidden=true;room.approach(point.id);};$('room-people').append(b);const label=document.createElement('button');label.className='town-label';label.textContent=point.door?'◇ '+point.name:point.name;label.onclick=()=>room.approach(point.id);$('town-labels').append(label);labels.set(point.id,label);}$('world').setAttribute('aria-label','Walkable town and interiors. WASD or arrow keys move in four directions. Click a place to approach it; E interacts.');$('leave-room').focus();}
function exit(){if(room.spec.parent){enter(room.spec.parent);return;}if(dialog.open)closeDialogue();positions.set(room.place,room.position);keys.clear();room.exit();document.body.classList.remove('in-room','in-town');$('room-ui').hidden=true;$('world').setAttribute('aria-label','Three-dimensional sailing world');save();onExit();}
$('leave-room').onclick=exit;
return{room,enter,exit,get dialogueOpen(){return dialog.open;},update(dt,blocked){room.update(dt,keys,blocked||dialog.open||!$('town-directory').hidden);for(const p of room.points){const el=labels.get(p.id);if(!el)continue;const v=room.project(p);el.style.left=v.x+'px';el.style.top=v.y+'px';el.hidden=!v.visible||dialog.open||(p.door&&Math.hypot(p.x-room.position.x,p.z-room.position.z)<3);}},key(e){if(!room.active)return false;if(dialog.open||document.getElementById('modal').open)return true;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!e.repeat){keys.delete(k);keys.add(k);if(k==='e')room.interact();if(k==='escape'){if(!$('town-directory').hidden)$('town-directory').hidden=true;else exit();}}return true;},journal(){const s=getState();return`<div class="journal-entry story-entry"><small>${s.story.phase==='complete'?'STORY COMPLETE':'PERSONAL STORY'}</small><h3>${STORY_TITLE}</h3><p>${objective(s)}</p><p class="story-items">${storyItems(s).length?'Keepsakes: '+storyItems(s).join(' · '):'A lantern burns in a Lisbon tavern for a captain who has not come home.'}</p>${s.story.phase==='complete'?`<p>Companion: ${CAST[s.story.companion].name}</p>`:'<button class="action-btn" id="journal-story-course">Chart the next destination</button>'}</div><div class="journal-entry"><small>${s.expedition.phase==='complete'?'EXPEDITION COMPLETE':'BEYOND THE HORIZON'}</small><h3>${EXPEDITION_TITLE}</h3><p>${expeditionObjective(s)}</p>${s.story.phase==='complete'&&s.expedition.phase!=='complete'?'<button class="action-btn" id="journal-expedition-course">Chart the expedition destination</button>':''}</div>`;},bindJournal(){const b=$('journal-story-course');if(b)b.onclick=()=>onCourse(storyDestination(getState()));const e=$('journal-expedition-course');if(e)e.onclick=()=>onCourse(getState().expedition.phase==='locked'?'lisbon':'alexandria');}};
}
